            @NotBlank @Size(max = 100) String user, @NotNull Long id,
            @NotNull @Pattern(regexp = SIGNED_AMOUNT) String amount, LocalDate date, @Size(max = 1000) String note,
            @Size(max = 120) String corrects) {
