391	        for (int i = 0; i < listed.size(); i++) {
392	            personOrder.put(listed.get(i).getId(), i);
393	        }
394	        return ids.stream().distinct()
395	                .flatMap(id -> claims.findByIdAndSheetId(id, sheetId).stream())
396	                .sorted(Comparator.<Claim>comparingInt(c -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
397	                        .thenComparing(Claim::getListed, Comparator.reverseOrder()))
398	                .toList();
399	    }
400	
401	    /**
402	     * The due on a claim's amount at the rate for the person's grade in force on the claim's date,
403	     * rounded to the cent as the claim rounds (see {@link Rounding}) and raised to the floor in force on the claim's date (a correction's is not); null with no
404	     * rate in force then.
405	     */
406	    public BigDecimal due(String sheetId, Person person, Claim claim) {
407	        Sheet sheet = sheets.sheet(sheetId);
408	        RoundingMode rounding = Rounding.mode(sheet, roundingDate(sheetId, claim));
409	        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
410	                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding))
411	                .map(due -> claim.isCorrection() ? due : due.max(sheet.floorOn(claim.getDate())))
412	                .orElse(null);
413	    }
414	
415	    /** The date a claim rounds by: its own, or for a correction that of the claim it corrects. */
416	    private LocalDate roundingDate(String sheetId, Claim claim) {
417	        if (!claim.isCorrection() || claim.getCorrects() == null) {
418	            return claim.getDate();
419	        }
420	        return Rounding.dateOf(claim, claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()));
421	    }
422	
423	    /** Log the claim's status as it is now: by the user, on the sheet's today, with its due as computed now. */
424	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
425	        claim.log(new ClaimLogEntry(claim.getStatus(), user, sheets.today(sheetId),
426	                dueText(charged(sheetId, person, claim))));
427	    }
428	
429	    private static String dueText(BigDecimal due) {
430	        return due == null ? "n/a" : due.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
431	    }
432	
433	    /** Whether the user is a clerk settling a claim whose figure is above the sheet's clerk limit. */
434	    private boolean aboveClerkLimit(String sheetId, String user, BigDecimal figure) {
435	        BigDecimal limit = sheets.clerkLimit(sheetId);
436	        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
437	    }
438	
439	    private boolean isSteward(String sheetId, String user) {
440	        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
441	    }
442	
443	    /**
444	     * The number a claim corrects: none unless its amount is negative, when it must name the number
445	     * of a SETTLED claim of the same person, else it is refused (400).
446	     */
447	    private String corrected(String sheetId, long personId, BigDecimal amount, String corrects) {
448	        if (amount.signum() >= 0) {
449	            return null;
450	        }
451	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId).stream()
452	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
453	        if (!settled) {
454	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
455	                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
456	        }
457	        return corrects;
458	    }
459	
460	    /** Refuse (422) a claim dated after its person's retirement date. */
461	    private static void refuseIfRetired(Person person, LocalDate date) {
462	        if (person.isRetired() && date.isAfter(person.getRetiredFrom())) {
463	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
464	                    "That claim's date is after its person's retirement date.");
465	        }
466	    }
467	
468	    private Person person(String sheetId, long personId) {
469	        return people.findByIdAndSheetId(personId, sheetId)
470	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
471	    }
472	
473	    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
474	        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
475	                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
476	    }
477	
478	    private LocalDate dateOrToday(String sheetId, LocalDate date) {
479	        return date != null ? date : sheets.today(sheetId);
480	    }
481	}
