742	/**
743	 * How a claim's live figures are rounded to the cent: half up when the claim is dated before the
744	 * sheet's policy date (its today when it has none), half to even when dated on or after it. A
745	 * correction rounds by the date of the claim it corrects, not its own.
746	 */
747	public final class Rounding {
748	
749	    private Rounding() {
750	    }
751	
752	    /** The rounding for a claim dated on the given date. */
753	    public static RoundingMode mode(Sheet sheet, LocalDate date) {
754	        LocalDate policy = sheet.getPolicyDate() != null ? sheet.getPolicyDate() : sheet.getToday();
755	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
756	    }
757	
758	    /**
759	     * The date a claim rounds by: its own, or for a correction the date of the claim it corrects,
760	     * found by number among the sheet's claims (its own when that claim is not among them).
761	     */
762	    public static LocalDate dateOf(Claim claim, Collection<Claim> sheetClaims) {
763	        if (!claim.isCorrection() || claim.getCorrects() == null) {
764	            return claim.getDate();
765	        }
766	        return sheetClaims.stream().filter(c -> claim.getCorrects().equals(c.getNumber())).findFirst()
767	                .map(Claim::getDate).orElse(claim.getDate());
768	    }
769	}
