772	import java.math.BigDecimal;
773	import java.time.temporal.ChronoUnit;
774	import net.officefloor.hq.app.sheet.Sheet;
775	
776	/**
777	 * The late charge on an overdue claim: the late percent in force on the claim's date of its figure for every
778	 * full 30 days it is overdue (OPEN or PENDING, and past its due-by on the sheet's today),
779	 * rounded to the cent as the claim rounds (see {@link Rounding}). A correction has none. Never bound by a statement; settling a claim fixes it into its due.
780	 */
781	public final class LateCharge {
782	
783	    /** The days overdue that each add one late percent. */
784	    private static final int PERIOD_DAYS = 30;
785	
786	    private LateCharge() {
787	    }
788	
789	    /** The figure with its late charge added on top; null when the figure is null. */
790	    public static BigDecimal withCharge(Sheet sheet, Claim claim, BigDecimal figure) {
791	        return figure == null ? null : figure.add(charge(sheet, claim, figure));
792	    }
793	
794	    /**
795	     * The figure with the late charge it would have on the sheet's today were the claim open,
796	     * whatever its status; null when the figure is null.
797	     */
798	    public static BigDecimal withChargeAsOpen(Sheet sheet, Claim claim, BigDecimal figure) {
799	        return figure == null ? null : figure.add(charge(sheet, claim, figure, true));
800	    }
801	
802	    /** The late charge on a claim's figure on the sheet's today; zero when it is not overdue. */
803	    public static BigDecimal charge(Sheet sheet, Claim claim, BigDecimal figure) {
804	        return charge(sheet, claim, figure, claim.getStatus().isOpen() && !claim.isDeferredOn(sheet.getToday()));
805	    }
806	
807	    private static BigDecimal charge(Sheet sheet, Claim claim, BigDecimal figure, boolean open) {
808	        BigDecimal zero = BigDecimal.ZERO.setScale(2);
809	        if (figure == null || !open || claim.isCorrection()) {
810	            return zero;
811	        }
812	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / PERIOD_DAYS;
813	        if (periods <= 0) {
814	            return zero;
815	        }
816	        return figure.multiply(sheet.latePctOn(claim.getDate())).multiply(BigDecimal.valueOf(periods))
817	                .divide(BigDecimal.valueOf(100), 2, Rounding.mode(sheet, claim.getDate()));
818	    }
819	}
820	package net.officefloor.hq.app.claim;
821	
822	/**
823	 * A claim's status: DRAFT when added; opened (OPEN), then settled (SETTLED). A clerk settling a
824	 * claim above the clerk limit makes it PENDING instead, until a steward approves it (SETTLED) or
825	 * rejects it (back to OPEN). A DRAFT, OPEN or PENDING claim can be voided (VOID). A SETTLED or VOID
826	 * claim cannot change status.
827	 */
828	public enum ClaimStatus {
829	    DRAFT, OPEN, PENDING, SETTLED, VOID;
830	
831	    /** Whether a claim in this status may move to the given one. */
832	    public boolean canBecome(ClaimStatus next) {
833	        return switch (next) {
834	            case OPEN -> this == DRAFT || this == PENDING;
835	            case PENDING -> this == OPEN;
836	            case SETTLED -> this == OPEN || this == PENDING;
837	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
838	            case DRAFT -> false;
839	        };
840	    }
841	
842	    /** Whether a claim in this status counts toward the totals: OPEN, PENDING and SETTLED do. */
843	    public boolean counts() {
844	        return this == OPEN || this == PENDING || this == SETTLED;
845	    }
846	
847	    /** Whether a claim in this status is open: OPEN or PENDING (it goes overdue, and a hold takes it out of the totals). */
848	    public boolean isOpen() {
849	        return this == OPEN || this == PENDING;
850	    }
851	}
