25	/**
26	 * The sheet's figures as the screen shows them: each person's claimed, due-total and overdue-total
27	 * (the figures of their overdue claims that count, not capped), and the sheet's totals of each. A change takes a {@link #snapshot} before it alters anything
28	 * and calls {@link #recordChanges} after its own audit lines, which appends one ROLLUP line per
29	 * person whose figures moved (people in the order they were added; a new person counts as moved),
30	 * then a TOTALS line when any of the sheet's totals moved. A held person's OPEN claims count in none of
31	 * these (nor their PENDING ones), nor in a period's due-total; their SETTLED claims still do. A live due is never below
32	 * the floor in force on its claim's date; an overdue claim's figure has its late charge added on top. A person's
33	 * due-total is at most the cap in force on the sheet's today, when there is one.
34	 */
35	@Service
36	public class RollupService {
37	
38	    /** A person's figures: claimed, due-total (null for n/a) and overdue-total. */
39	    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
40	    }
41	
42	    /** The sheet's figures: each person's by id, in the order they were added. */
43	    public record Snapshot(Map<Long, Figures> people) {
44	
45	        public BigDecimal claimedTotal() {
46	            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
47	        }
48	
49	        public BigDecimal dueTotal() {
50	            return people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull).reduce(zero(),
51	                    BigDecimal::add);
52	        }
53	
54	        public BigDecimal overdueTotal() {
55	            return people.values().stream().map(Figures::overdueTotal).reduce(zero(), BigDecimal::add);
56	        }
57	    }
58	
59	    private final PersonRepository people;
60	    private final ClaimRepository claims;
61	    private final RateRepository rates;
62	    private final SheetRepository sheets;
63	    private final Audit audit;
64	
65	    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
66	            Audit audit) {
67	        this.people = people;
68	        this.claims = claims;
69	        this.rates = rates;
70	        this.sheets = sheets;
71	        this.audit = audit;
72	    }
73	
74	    /** The sheet's figures as the store holds them now. */
75	    public Snapshot snapshot(String sheetId) {
76	        Sheet sheet = sheet(sheetId);
77	        LocalDate today = sheet.getToday();
78	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
79	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
80	        Map<Long, Figures> figures = new LinkedHashMap<>();
81	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
82	            BigDecimal claimed = zero();
83	            BigDecimal due = zero();
84	            BigDecimal overdue = zero();
85	            boolean anyFigure = false;
86	            for (Claim claim : sheetClaims) {
87	                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, today)) {
88	                    continue;
89	                }
90	                claimed = claimed.add(claim.getAmount());
91	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
92	                if (figure != null) {
93	                    anyFigure = true;
94	                    due = due.add(figure);
95	                    if (overdue(claim, today)) {
96	                        overdue = overdue.add(figure);
97	                    }
98	                }
99	            }
100	            // as on screen: n/a when the grade in force today has no rate today and no claim that
101	            // counts has a figure
102	            boolean none = inForce(sheetRates, person.gradeOn(today), today).isEmpty() && !anyFigure;
103	            figures.put(person.getId(), new Figures(person.getName(), claimed, none ? null : sheet.capped(due),
104	                    overdue));
105	        }
106	        return new Snapshot(figures);
107	    }
108	
109	    /**
110	     * Each person's due of their claims that count whose date falls in from..to (both inclusive),
111	     * by person id, for every person on the sheet (0.00 when none).
112	     */
113	    public Map<Long, BigDecimal> dueBetweenByPerson(String sheetId, LocalDate from, LocalDate to) {
114	        Sheet sheet = sheet(sheetId);
115	        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
116	        List<Claim> sheetClaims = claims.findBySheetIdOrderByIdDesc(sheetId);
117	        Map<Long, BigDecimal> dues = new LinkedHashMap<>();
118	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
119	            BigDecimal due = zero();
120	            for (Claim claim : sheetClaims) {
121	                if (!claim.getPersonId().equals(person.getId()) || !person.counts(claim, sheet.getToday())
122	                        || claim.getDate().isBefore(from) || claim.getDate().isAfter(to)) {
123	                    continue;
124	                }
125	                BigDecimal figure = figure(sheet, sheetRates, sheetClaims, person, claim);
126	                if (figure != null) {
127	                    due = due.add(figure);
128	                }
129	            }
130	            dues.put(person.getId(), due);
131	        }
132	        return dues;
133	    }
134	
135	    /** Record, once the change commits, the figures that moved since the snapshot taken before it. */
136	    public void recordChanges(String sheetId, String user, Snapshot before) {
137	        Snapshot after = snapshot(sheetId);
138	        String prefix = " sheet=" + sheetId + " by=" + user;
139	        boolean moved = false;
140	        for (Map.Entry<Long, Figures> entry : after.people().entrySet()) {
141	            Figures now = entry.getValue();
142	            Figures was = before.people().get(entry.getKey());
143	            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
144	                    && same(was.overdueTotal(), now.overdueTotal())) {
145	                continue;
146	            }
147	            moved = true;
148	            audit.recordOnCommit("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + money(now.claimed())
149	                    + " due-total=" + money(now.dueTotal()) + " overdue-total=" + money(now.overdueTotal()));
150	        }
151	        if (moved && !(same(before.claimedTotal(), after.claimedTotal())
152	                && same(before.dueTotal(), after.dueTotal()) && same(before.overdueTotal(), after.overdueTotal()))) {
153	            audit.recordOnCommit("TOTALS" + prefix + " claimed-total=" + money(after.claimedTotal()) + " due-total="
154	                    + money(after.dueTotal()) + " overdue-total=" + money(after.overdueTotal()));
155	        }
156	    }
157	
158	    /**
159	     * A claim's figure as the screen shows it: the due fixed when settled, else the one bound by the
160	     * last statement (not while PENDING), else its live due (rounded as the claim rounds, see {@link Rounding}) raised to the floor (a correction's is not), with its late charge added on top;
161	     * null when none.
162	     */
163	    private static BigDecimal figure(Sheet sheet, List<Rate> sheetRates, List<Claim> sheetClaims, Person person,
164	            Claim claim) {
165	        if (claim.getStatus() == ClaimStatus.SETTLED && claim.getSettledDue() != null) {
166	            return claim.getSettledDue();
167	        }
168	        BigDecimal figure = claim.isStated() && claim.getStatus() != ClaimStatus.PENDING ? claim.getStatedDue()
169	                : inForce(sheetRates, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
170	                        .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2,
171	                                Rounding.mode(sheet, Rounding.dateOf(claim, sheetClaims))))
172	                        .map(due -> claim.isCorrection() ? due : due.max(sheet.floorOn(claim.getDate())))
173	                        .orElse(null);
174	        return LateCharge.withCharge(sheet, claim, figure);
175	    }
176	
177	    /** Whether a claim is overdue on the sheet's today: OPEN or PENDING, not deferred, and past its due-by. */
178	    private static boolean overdue(Claim claim, LocalDate today) {
179	        return claim.getStatus().isOpen() && !claim.isDeferredOn(today) && today != null && claim.getDueBy() != null
180	                && claim.getDueBy().isBefore(today);
181	    }
182	
183	    private Sheet sheet(String sheetId) {
184	        return sheets.findById(sheetId).orElseGet(() -> new Sheet(sheetId, null, null, LocalDate.now()));
185	    }
186	
187	    /** The grade's rate in force on a date, as {@link RateRepository#findInForce} picks it. */
188	    private static Optional<Rate> inForce(List<Rate> sheetRates, String grade, LocalDate date) {
189	        return sheetRates.stream().filter(r -> r.getGrade().equals(grade))
190	                .filter(r -> r.getFromDate() == null || !r.getFromDate().isAfter(date))
191	                .max((a, b) -> a.getFromDate() == null ? -1 : b.getFromDate() == null ? 1
192	                        : a.getFromDate().compareTo(b.getFromDate()))
193	                .filter(r -> r.runsThrough(date));
194	    }
195	
196	    private static boolean same(BigDecimal a, BigDecimal b) {
197	        return a == null ? b == null : b != null && a.compareTo(b) == 0;
198	    }
199	
200	    private static BigDecimal zero() {
201	        return BigDecimal.ZERO.setScale(2);
202	    }
203	
204	    private static String money(BigDecimal value) {
205	        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
206	    }
207	}
