334	import java.time.LocalDate;
335	import java.util.List;
336	import java.math.BigDecimal;
337	import java.math.RoundingMode;
338	import net.officefloor.hq.app.Audit;
339	import net.officefloor.hq.app.role.Role;
340	import net.officefloor.hq.app.role.RoleService;
341	import net.officefloor.hq.app.rollup.RollupService;
342	import net.officefloor.hq.app.sheet.SheetRepository;
343	import net.officefloor.hq.app.sheet.SheetService;
344	import org.springframework.dao.DataIntegrityViolationException;
345	import org.springframework.http.HttpStatus;
346	import org.springframework.stereotype.Service;
347	import org.springframework.transaction.annotation.Transactional;
348	import org.springframework.web.server.ResponseStatusException;
349	
350	/**
351	 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
352	 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
353	 * closed once: closing fixes its due-total at that moment, and no claim dated inside a closed
354	 * period can be added, edited, opened, settled or voided. A steward can reopen a closed period, which
355	 * makes its due-total live again.
356	 */
357	@Service
358	public class PeriodService {
359	
360	    private final PeriodRepository periods;
361	    private final SheetService sheets;
362	    private final SheetRepository sheetRows;
363	    private final Audit audit;
364	    private final RollupService rollup;
365	    private final RoleService roles;
366	
367	    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
368	            RollupService rollup, RoleService roles) {
369	        this.rollup = rollup;
370	        this.roles = roles;
371	        this.periods = periods;
372	        this.sheets = sheets;
373	        this.sheetRows = sheetRows;
374	        this.audit = audit;
375	    }
376	
377	    @Transactional(readOnly = true)
378	    public List<Period> list(String sheetId) {
379	        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
380	    }
381	
382	    @Transactional
383	    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
384	        if (to.isBefore(from)) {
385	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
386	        }
387	        sheets.load(sheetId, user);
388	        // hold the sheet so two periods added at the same moment are checked one after the other
389	        sheetRows.findLockedById(sheetId);
390	        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
391	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
392	        }
393	        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
394	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
395	        }
396	        Period added;
397	        try {
398	            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
399	        } catch (DataIntegrityViolationException e) {
400	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
401	        }
402	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
403	                + added.getFromDate() + " to=" + added.getToDate());
404	        return added;
405	    }
406	
407	    /** Close a period, fixing its due-total now; refused (409) when it is already closed. */
408	    @Transactional
409	    public Period close(String sheetId, String user, long id) {
410	        // hold the sheet so no claim changes while the period's due-total is fixed
411	        sheetRows.findLockedById(sheetId)
412	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
413	        Period period = periods.findByIdAndSheetId(id, sheetId)
414	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
415	        if (period.isClosed()) {
416	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is already closed.");
417	        }
418	        period.close(rollup.dueBetweenByPerson(sheetId, period.getFromDate(), period.getToDate()));
419	        Period saved = periods.saveAndFlush(period);
420	        BigDecimal due = saved.getClosedDue();
421	        audit.recordOnCommit("PERIOD_CLOSED sheet=" + sheetId + " by=" + user + " period=" + saved.getName()
422	                + " total=" + due.setScale(2, RoundingMode.UNNECESSARY).toPlainString());
423	        return saved;
424	    }
425	
426	    /**
427	     * Reopen a closed period, making its due-total live again; refused (403) for anyone but a
428	     * steward and (409) when the period is not closed.
429	     */
430	    @Transactional
431	    public Period reopen(String sheetId, String user, long id) {
432	        sheetRows.findLockedById(sheetId)
433	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
434	        Period period = periods.findByIdAndSheetId(id, sheetId)
435	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such period on this sheet."));
436	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
437	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can reopen a period.");
438	        }
439	        if (!period.isClosed()) {
440	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period is not closed.");
441	        }
442	        period.reopen();
443	        Period saved = periods.saveAndFlush(period);
444	        audit.recordOnCommit("PERIOD_REOPENED sheet=" + sheetId + " by=" + user + " period=" + saved.getName());
445	        return saved;
446	    }
447	
448	    /**
449	     * Refuse (423) a change to a claim dated inside a closed period. Holds the sheet first, so a
450	     * period cannot close while the change is under way.
451	     */
452	    public void refuseIfClosed(String sheetId, LocalDate date) {
453	        if (isClosed(sheetId, date)) {
454	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period.");
455	        }
456	    }
457	
458	    /**
459	     * Whether a claim dated on this day lies inside a closed period. Holds the sheet first, so a
460	     * period cannot close while a change that relies on the answer is under way.
461	     */
462	    public boolean isClosed(String sheetId, LocalDate date) {
463	        sheetRows.findLockedById(sheetId);
464	        return periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date,
465	                date);
466	    }
467	}
