491	/**
492	 * Statements on a sheet. Taking a person's statement records their due-total at that moment, taken
493	 * on the sheet's today (held to the sheet's cap), and binds every claim of theirs that counts (OPEN, PENDING or SETTLED, but not a held
494	 * person's OPEN or PENDING claims) to the figure it has then; a claim of theirs that does not count is unbound,
495	 * so its figure is live again. The late charge is never bound: the due-total includes each claim's charge on the day, but a claim is
496	 * bound to the figure under it.
497	 */
498	@Service
499	public class StatementService {
500	
501	    /** A person's statements: how many, and the last one (none before the first). */
502	    public record Summary(long personId, int count, Statement last) {
503	    }
504	
505	    /** A statement just taken, with the person's claims as it left them. */
506	    public record Taken(Summary summary, List<Claim> claims) {
507	    }
508	
509	    private final StatementRepository statements;
510	    private final PersonRepository people;
511	    private final ClaimRepository claims;
512	    private final ClaimService claimService;
513	    private final RateRepository rates;
514	    private final SheetService sheets;
515	    private final Audit audit;
516	    private final RollupService rollup;
517	
518	    public StatementService(StatementRepository statements, PersonRepository people, ClaimRepository claims,
519	            ClaimService claimService, RateRepository rates, SheetService sheets, Audit audit, RollupService rollup) {
520	        this.rollup = rollup;
521	        this.statements = statements;
522	        this.people = people;
523	        this.claims = claims;
524	        this.claimService = claimService;
525	        this.rates = rates;
526	        this.sheets = sheets;
527	        this.audit = audit;
528	    }
529	
530	    /** Each person's statements on the sheet who has taken any. */
531	    @Transactional(readOnly = true)
532	    public List<Summary> list(String sheetId) {
533	        Map<Long, Summary> by = new LinkedHashMap<>();
534	        for (Statement s : statements.findBySheetIdOrderByIdAsc(sheetId)) {
535	            Summary was = by.get(s.getPersonId());
536	            by.put(s.getPersonId(), new Summary(s.getPersonId(), was == null ? 1 : was.count() + 1, s));
537	        }
538	        return List.copyOf(by.values());
539	    }
540	
541	    @Transactional
542	    public Taken take(String sheetId, String user, long personId) {
543	        Person person = people.lockByIdAndSheetId(personId, sheetId)
544	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
545	        LocalDate today = sheets.today(sheetId);
546	        RollupService.Snapshot before = rollup.snapshot(sheetId);
547	        List<Claim> theirs = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
548	        BigDecimal total = BigDecimal.ZERO.setScale(2);
549	        boolean anyFigure = false;
550	        int counted = 0;
551	        for (Claim claim : theirs) {
552	            if (person.counts(claim, today)) {
553	                BigDecimal figure = claimService.figure(sheetId, person, claim);
554	                BigDecimal charged = claimService.charged(sheetId, person, claim);
555	                claim.bind(true, figure);
556	                if (charged != null) {
557	                    total = total.add(charged);
558	                    anyFigure = true;
559	                }
560	                counted++;
561	            } else {
562	                claim.bind(false, null);
563	            }
564	        }
565	        claims.saveAllAndFlush(theirs);
566	        // as on screen: n/a when the grade has no rate today and no claim that counts has a figure
567	        BigDecimal dueTotal = anyFigure || rates.findInForce(sheetId, person.gradeOn(today), today).isPresent() ? sheets.capped(sheetId, total) : null;
568	        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
569	        int count = (int) statements.findBySheetIdOrderByIdAsc(sheetId).stream()
570	                .filter(s -> Objects.equals(s.getPersonId(), personId)).count();
571	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
572	                + " due-total=" + money(dueTotal) + " claims=" + counted);
573	        rollup.recordChanges(sheetId, user, before);
574	        return new Taken(new Summary(personId, count, taken), theirs);
575	    }
576	
577	    public static String money(BigDecimal value) {
578	        return value == null ? "n/a" : value.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
579	    }
580	}
