810	import java.math.BigDecimal;
811	import java.math.RoundingMode;
812	import java.time.LocalDate;
813	import java.util.Map;
814	import java.util.TreeMap;
815	import net.officefloor.hq.app.Audit;
816	import net.officefloor.hq.app.claim.Rounding;
817	import net.officefloor.hq.app.rollup.RollupService;
818	import net.officefloor.hq.app.sheet.Sheet;
819	import net.officefloor.hq.app.sheet.SheetRepository;
820	import net.officefloor.hq.app.sheet.SheetService;
821	import org.springframework.stereotype.Service;
822	import org.springframework.transaction.annotation.Transactional;
823	
824	/**
825	 * The sheet's settings: its clerk limit (none: no limit) and its floor, the least a claim's live due
826	 * can be, and its terms, the days after its date a claim is due by, and its late percent, what an
827	 * overdue claim gains of its figure for every full 30 days overdue. Changing the floor or the late
828	 * percent moves the figures, so the figures that move are recorded. Its policy date (none:
829	 * the sheet's today) decides how a claim's live figures round (see {@link Rounding}), so changing it
830	 * records the figures that move too. Its period-numbering-from date (none: off) decides how a claim
831	 * opened is numbered: on or after it, within its period (see {@link SheetService#nextClaimNumber}).
832	 * Its cap (none: no cap) is the most a person's due-total can be, so changing it records the
833	 * figures that move too. A grade may have its own terms; a grade without uses the sheet's terms. A claim's due-by is fixed
834	 * when it is created, so changing any terms moves no claim's due-by.
835	 * <p>
836	 * The settings that carry a figure (the floor, the late percent, the terms, a grade's own terms,
837	 * the clerk limit and the cap) are dated: each value is recorded from a from-date (the sheet's
838	 * today when none is given). A claim's floor, late percent and terms are those in force on its
839	 * date; the clerk limit and the cap are those in force on the sheet's today (see {@link Sheet}).
840	 * The policy date and the period-numbering-from date are not dated.
841	 */
842	@Service
843	public class SettingService {
844	
845	    public static final String CLERK_LIMIT = Sheet.CLERK_LIMIT;
846	    public static final String FLOOR = Sheet.FLOOR;
847	    public static final String CAP = Sheet.CAP;
848	    public static final String TERMS = Sheet.TERMS;
849	    /** The key of a grade's own terms: {@code terms-<grade>}. */
850	    public static final String GRADE_TERMS = Sheet.GRADE_TERMS;
851	    public static final String LATE_PCT = Sheet.LATE_PCT;
852	    public static final String POLICY_DATE = "policy-date";
853	    public static final String PERIOD_NUMBERING_FROM = "period-numbering-from";
854	
855	    private final SheetService sheets;
856	    private final SheetRepository sheetStore;
857	    private final RollupService rollup;
858	    private final Audit audit;
859	
860	    public SettingService(SheetService sheets, SheetRepository sheetStore, RollupService rollup, Audit audit) {
861	        this.sheets = sheets;
862	        this.sheetStore = sheetStore;
863	        this.rollup = rollup;
864	        this.audit = audit;
865	    }
866	
867	    @Transactional
868	    public Sheet get(String sheetId, String user) {
869	        return sheets.load(sheetId, user);
870	    }
871	
872	    /**
873	     * A value to record for a setting that carries a figure (null for none: no limit, no cap) from
874	     * a from-date (null: from the sheet's today, and the record names no from-date).
875	     */
876	    public record Dated<T>(T value, LocalDate from) {
877	    }
878	
879	    /**
880	     * Save the settings given: a clerk limit when {@code limit} is not null, and the floor, the
881	     * terms and the late percent when they are not null, and a policy date when {@code changePolicy}
882	     * (null for none), and a period-numbering-from date when {@code changeNumbering} (null for off),
883	     * and a cap when {@code cap} is not null, and each grade's own terms given in {@code gradeTerms}
884	     * (by grade, in grade order). Each figure is recorded from its from-date, keeping the values
885	     * already recorded (one already recorded from that date is replaced). Each one saved is
886	     * recorded, in that order.
887	     */
888	    @Transactional
889	    public Sheet set(String sheetId, String user, Dated<BigDecimal> limit, Dated<BigDecimal> floor,
890	            Dated<Integer> terms, Dated<BigDecimal> latePct, boolean changePolicy, LocalDate policyDate,
891	            boolean changeNumbering, LocalDate numberingFrom, Dated<BigDecimal> cap,
892	            Map<String, Dated<Integer>> gradeTerms) {
893	        Sheet sheet = sheets.load(sheetId, user);
894	        if (limit != null) {
895	            sheet = record(sheet, user, CLERK_LIMIT, limit.value(), limit.from(), text(limit.value()), false);
896	        }
897	        if (floor != null) {
898	            sheet = record(sheet, user, FLOOR, floor.value(), floor.from(), text(floor.value()), true);
899	        }
900	        if (terms != null) {
901	            sheet = record(sheet, user, TERMS, BigDecimal.valueOf(terms.value()), terms.from(),
902	                    String.valueOf(terms.value()), false);
903	        }
904	        if (latePct != null) {
905	            sheet = record(sheet, user, LATE_PCT, latePct.value(), latePct.from(), text(latePct.value()), true);
906	        }
907	        if (changePolicy) {
908	            RollupService.Snapshot before = rollup.snapshot(sheetId);
909	            sheet.setPolicyDate(policyDate);
910	            sheet = sheetStore.saveAndFlush(sheet);
911	            audit.recordOnCommit(changed(sheetId, user, POLICY_DATE, policyDate == null ? "" : policyDate.toString()));
912	            rollup.recordChanges(sheetId, user, before);
913	        }
914	        if (changeNumbering) {
915	            sheet.setPeriodNumberingFrom(numberingFrom);
916	            sheet = sheetStore.saveAndFlush(sheet);
917	            audit.recordOnCommit(changed(sheetId, user, PERIOD_NUMBERING_FROM,
918	                    numberingFrom == null ? "" : numberingFrom.toString()));
919	        }
920	        if (cap != null) {
921	            sheet = record(sheet, user, CAP, cap.value(), cap.from(), text(cap.value()), true);
922	        }
923	        for (Map.Entry<String, Dated<Integer>> e : new TreeMap<>(gradeTerms).entrySet()) {
924	            Dated<Integer> t = e.getValue();
925	            sheet = record(sheet, user, GRADE_TERMS + e.getKey(), BigDecimal.valueOf(t.value()), t.from(),
926	                    String.valueOf(t.value()), false);
927	        }
928	        return sheet;
929	    }
930	
931	    /**
932	     * Record a setting's value from a from-date (null: the sheet's today) and audit it; when it
933	     * {@code moves} the figures, the figures that move are recorded too.
934	     */
935	    private Sheet record(Sheet sheet, String user, String key, BigDecimal value, LocalDate from, String text,
936	            boolean moves) {
937	        String sheetId = sheet.getId();
938	        RollupService.Snapshot before = moves ? rollup.snapshot(sheetId) : null;
939	        sheet.record(key, from != null ? from : sheet.getToday(), value);
940	        Sheet saved = sheetStore.saveAndFlush(sheet);
941	        audit.recordOnCommit(changed(sheetId, user, key, text) + (from != null ? " from=" + from : ""));
942	        if (moves) {
943	            rollup.recordChanges(sheetId, user, before);
944	        }
945	        return saved;
946	    }
947	
948	    private static String changed(String sheetId, String user, String key, String value) {
949	        return "SETTING_CHANGED sheet=" + sheetId + " by=" + user + " key=" + key + " value=" + value;
950	    }
951	
952	    /** A limit with two decimals, or blank for none. */
953	    public static String text(BigDecimal limit) {
954	        return limit == null ? "" : limit.setScale(2, RoundingMode.UNNECESSARY).toPlainString();
955	    }
956	}
